32	
33	    /// <summary>
34	    /// Creates an instance of the <see cref="AzureOpenAITextToAudioClient"/> with API key auth.
35	    /// </summary>
36	    /// <param name="deploymentName">Azure OpenAI deployment name, see https://learn.microsoft.com/azure/cognitive-services/openai/how-to/create-resource</param>
37	    /// <param name="endpoint">Azure OpenAI deployment URL, see https://learn.microsoft.com/azure/cognitive-services/openai/quickstart</param>
38	    /// <param name="apiKey">Azure OpenAI API key, see https://learn.microsoft.com/azure/cognitive-services/openai/quickstart</param>
39	    /// <param name="modelId">Azure OpenAI model id, see https://learn.microsoft.com/azure/cognitive-services/openai/how-to/create-resource</param>
40	    /// <param name="httpClient">Custom <see cref="HttpClient"/> for HTTP requests.</param>
41	    /// <param name="logger">The <see cref="ILogger"/> to use for logging. If null, no logging will be performed.</param>
42	    internal AzureOpenAITextToAudioClient(
43	        string deploymentName,
44	        string endpoint,
45	        string apiKey,
46	        string? modelId = null,
47	        HttpClient? httpClient = null,
48	        ILogger? logger = null)
49	    {
50	        Verify.NotNullOrWhiteSpace(deploymentName);
51	        Verify.NotNullOrWhiteSpace(endpoint);
52	        Verify.StartsWith(endpoint, "https://", "The Azure OpenAI endpoint must start with 'https://'");
53	        Verify.NotNullOrWhiteSpace(apiKey);
54	
55	        this._deploymentName = deploymentName;
56	        this._endpoint = endpoint;
57	        this._apiKey = apiKey;
58	        this._modelId = modelId;
59	
60	        this._httpClient = HttpClientProvider.GetHttpClient(httpClient);
61	        this._logger = logger ?? NullLogger.Instance;
62	    }
63	
64	    internal async Task<IReadOnlyList<AudioContent>> GetAudioContentsAsync(
65	        string text,
66	        PromptExecutionSettings? executionSettings,
67	        CancellationToken cancellationToken)
68	    {
69	        OpenAITextToAudioExecutionSettings? audioExecutionSettings = OpenAITextToAudioExecutionSettings.FromExecutionSettings(executionSettings);
70	
71	        Verify.NotNullOrWhiteSpace(audioExecutionSettings?.Voice);
72	
73	        var modelId = this.GetModelId(audioExecutionSettings);
74	
75	        using var request = this.GetRequest(text, modelId, audioExecutionSettings);
76	        using var response = await this.SendRequestAsync(request, cancellationToken).ConfigureAwait(false);
77	        var data = await response.Content.ReadAsByteArrayAndTranslateExceptionAsync().ConfigureAwait(false);
78	
79	        return [new(data, modelId)];
80	    }
81	
82	    internal void AddAttribute(string key, string? value)
83	    {
84	        if (!string.IsNullOrEmpty(value))
85	        {
86	            this.Attributes.Add(key, value);
87	        }
88	    }
