91	
92	    private async Task<HttpResponseMessage> SendRequestAsync(
93	        HttpRequestMessage request,
94	        CancellationToken cancellationToken)
95	    {
96	        request.Headers.Add("User-Agent", HttpHeaderConstant.Values.UserAgent);
97	        request.Headers.Add("Api-Key", this._apiKey);
98	        request.Headers.Add(HttpHeaderConstant.Names.SemanticKernelVersion, HttpHeaderConstant.Values.GetAssemblyVersion(typeof(AzureOpenAITextToAudioClient)));
99	
100	        try
101	        {
102	            return await this._httpClient.SendWithSuccessCheckAsync(request, cancellationToken).ConfigureAwait(false);
103	        }
104	        catch (HttpOperationException ex)
105	        {
106	            this._logger.LogError(
107	                "Error occurred on text-to-audio request execution: {ExceptionMessage}", ex.Message);
108	
109	            throw;
110	        }
111	    }
112	
113	    private HttpRequestMessage GetRequest(string text, string modelId, OpenAITextToAudioExecutionSettings executionSettings)
114	    {
115	        const string DefaultApiVersion = "2024-02-15-preview";
116	
117	        var baseUrl = !string.IsNullOrWhiteSpace(this._httpClient.BaseAddress?.AbsoluteUri) ?
118	            this._httpClient.BaseAddress!.AbsoluteUri :
119	            this._endpoint;
120	
121	        var requestUrl = $"openai/deployments/{this._deploymentName}/audio/speech?api-version={DefaultApiVersion}";
122	
123	        var payload = new TextToAudioRequest(modelId, text, executionSettings.Voice)
124	        {
125	            ResponseFormat = executionSettings.ResponseFormat,
126	            Speed = executionSettings.Speed
127	        };
128	
129	        return HttpRequest.CreatePostRequest($"{baseUrl.TrimEnd('/')}/{requestUrl}", payload);
130	    }
131	
132	    private string GetModelId(OpenAITextToAudioExecutionSettings executionSettings)
133	    {
134	        return
135	            !string.IsNullOrWhiteSpace(this._modelId) ? this._modelId! :
136	            !string.IsNullOrWhiteSpace(executionSettings.ModelId) ? executionSettings.ModelId! :
137	            this._deploymentName;
138	    }
139	
140	    #endregion
141	}
