    [Fact]
    public void ConstructorSetsAttributes()
    {
        var service = new AzureOpenAITextToAudioService("deployment-name", "https://endpoint", "api-key", "model-id");
        Assert.Equal("model-id", service.Attributes["ModelId"]);
        Assert.Equal("deployment-name", service.Attributes["DeploymentName"]);
    }

    [Fact]
    public void NullDeploymentThrowsArgumentNull()
        => Assert.Throws<ArgumentNullException>(() => new AzureOpenAITextToAudioService(null!, "https://endpoint", "api-key"));

    [Theory]
    [InlineData("")]
    [InlineData(" ")]
    public void EmptyDeploymentThrowsArgument(string deployment)
        => Assert.Throws<ArgumentException>(() => new AzureOpenAITextToAudioService(deployment, "https://endpoint", "api-key"));

    [Fact]
    public async Task EmptyVoiceThrowsNotSupported()
    {
        var service = new AzureOpenAITextToAudioService("deployment-name", "https://endpoint", "api-key", "model-id", this._httpClient);
        this._stub.ResponseToReturn = new HttpResponseMessage(HttpStatusCode.OK) { Content = new StreamContent(new MemoryStream([0x00])) };
        await Assert.ThrowsAsync<NotSupportedException>(() => service.GetAudioContentsAsync("text", new AzureOpenAITextToAudioExecutionSettings("")));
    }

    [Fact]
    public async Task UnsupportedFormatThrowsNotSupported()
    {
        var service = new AzureOpenAITextToAudioService("deployment-name", "https://endpoint", "api-key", "model-id", this._httpClient);
        await Assert.ThrowsAsync<NotSupportedException>(() => service.GetAudioContentsAsync("text", new AzureOpenAITextToAudioExecutionSettings("alloy") { ResponseFormat = "bogus" }));
    }

    [Fact]
    public async Task DefaultReturnsBytes()
    {
        byte[] expected = [0x00, 0x00, 0xFF, 0x7F];
        var service = new AzureOpenAITextToAudioService("deployment-name", "https://endpoint", "api-key", "model-id", this._httpClient);
        this._stub.ResponseToReturn = new HttpResponseMessage(HttpStatusCode.OK) { Content = new StreamContent(new MemoryStream(expected)) };
        var result = await service.GetAudioContentsAsync("text", new AzureOpenAITextToAudioExecutionSettings("alloy"));
        Assert.True(result[0].Data!.Value.Span.SequenceEqual(expected));
    }

    [Theory]
    [InlineData("echo", "wav")]
    [InlineData("nova", "aac")]
    public async Task VoicesAndFormatsInBody(string voice, string format)
    {
        byte[] expected = [0x00, 0x00, 0xFF, 0x7F];
        var service = new AzureOpenAITextToAudioService("deployment-name", "https://endpoint", "api-key", "model-id", this._httpClient);
        this._stub.ResponseToReturn = new HttpResponseMessage(HttpStatusCode.OK) { Content = new StreamContent(new MemoryStream(expected)) };
        await service.GetAudioContentsAsync("text", new AzureOpenAITextToAudioExecutionSettings(voice) { ResponseFormat = format });
        var body = Encoding.UTF8.GetString(this._stub.RequestContent!);
        Assert.Contains($"\"voice\":\"{voice}\"", body);
        Assert.Contains($"\"response_format\":\"{format}\"", body);
        Assert.Contains("\"model\":", body);
    }

